/bin/bash -c "python3 - <<'PY'
import re, statistics
from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
for i in (12,14):
 rows=[]
 for line in r.pages[i].extract_text(extraction_mode='layout').splitlines():
  m=re.match(r'"'^'"\\s*([a-z ]+)\\s+(-?\\d+\\.\\d+)\\s+(-?\\d+\\.\\d+)\\s+(-?\\d+\\.\\d+)',line)
  if m:
   rows.append((m[1].strip(),*[float(m[j]) for j in (2,3,4)]))
 print('page',i+1,'rows',len(rows))
 if i==12:
  print('Means single SS, single %F, paired SS:',[statistics.mean(row[j] for row in rows) for j in (1,2,3)])
  print('Mean absolute single SS:',statistics.mean(abs(row[1]) for row in rows))
  for subset in [rows[:20],rows[20:]]:
   print('Group means single SS, single %F, paired SS:',[statistics.mean(row[j] for row in subset) for j in (1,2,3)])
 else:
  print('Means single SS, paired SS, gap:',[statistics.mean(row[j] for row in rows) for j in (1,2,3)])
  for group in ['minor','power']:
   rr=[row for row in rows if row[0].endswith(group)]
   print(group,len(rr),'mean SS single',statistics.mean(row[1] for row in rr),'paired',statistics.mean(row[2] for row in rr))
PY"
